func Reconcile(ctx context.Context, req Request) (Result, error) {
    // 1. OBSERVE desired state
    cr := &MyApp{}
    if err := r.Get(ctx, req.NamespacedName, cr); err != nil {
        return ctrl.Result{}, client.IgnoreNotFound(err)
    }

    // 2. OBSERVE actual state (from informer cache)
    dep := &appsv1.Deployment{}
    if err := r.Get(ctx, childName(cr), dep); err != nil {
        if apierrors.IsNotFound(err) {
            // 3. ACT — create missing child
            return ctrl.Result{}, r.Create(ctx, buildDeployment(cr))
        }
        return ctrl.Result{}, err
    }

    // 4. DIFF — patch only if needed
    if dep.Spec.Replicas != cr.Spec.Replicas {
        dep.Spec.Replicas = cr.Spec.Replicas
        return ctrl.Result{}, r.Update(ctx, dep)
    }

    // Diff is zero — do nothing
    return ctrl.Result{}, nil
}

const myFinalizer = "example.com/cleanup"

func (r *Reconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    obj := &MyResource{}
    r.Get(ctx, req.NamespacedName, obj)

    if obj.DeletionTimestamp.IsZero() {
        // Ensure our finalizer is registered
        if !controllerutil.ContainsFinalizer(obj, myFinalizer) {
            controllerutil.AddFinalizer(obj, myFinalizer)
            return ctrl.Result{}, r.Update(ctx, obj)
        }
    } else {
        // Object is being deleted
        if controllerutil.ContainsFinalizer(obj, myFinalizer) {
            if err := r.deleteExternalResources(obj); err != nil {
                return ctrl.Result{}, err // retry with back-off
            }
            controllerutil.RemoveFinalizer(obj, myFinalizer)
            return ctrl.Result{}, r.Update(ctx, obj)
        }
    }
    return ctrl.Result{}, nil
}
